# pairwise corr over last 60 common days
last60 = common[-60:]
pairs = []
for i in range(len(TRADABLE)):
    for j in range(i+1, len(TRADABLE)):
        a = [dr_mat[d].get(TRADABLE[i]) for d in last60]
        b = [dr_mat[d].get(TRADABLE[j]) for d in last60]
        pts = [(x,y) for x,y in zip(a,b) if x is not None and y is not None]
        if len(pts) < 30: continue
        xs = [p[0] for p in pts]; ys = [p[1] for p in pts]
        n = len(xs); mx = sum(xs)/n; my = sum(ys)/n
        cov = sum((xs[k]-mx)*(ys[k]-my) for k in range(n))/(n-1)
        vx = sum((x-mx)**2 for x in xs)/(n-1); vy = sum((y-my)**2 for y in ys)/(n-1)
        if vx == 0 or vy == 0: continue
